from flask import Flask, jsonify
import requests, datetime
app = Flask(__name__)
@app.route('/')
def home():
 return open(__file__,encoding='utf-8').read().split("#HTML#")[1]
@app.route('/api/league30/<lg>')
def api(lg):
 live=[];up=[]
 for i in range(1,90):
  d=(datetime.datetime.now()+datetime.timedelta(days=i)).strftime("%Y%m%d")
  try:
   r=requests.get(f"https://site.api.espn.com/apis/site/v2/sports/soccer/{lg}/scoreboard?dates={d}",timeout=5)
   for ev in r.json().get('events',[]):
    c=ev['competitions'][0];c0=c['competitors'][0];c1=c['competitors'][1]
    up.append({"home":c0['team']['displayName'],"away":c1['team']['displayName'],"homeLogo":c0['team'].get('logo',''),"awayLogo":c1['team'].get('logo',''),"league":lg,"date":d,"isLive":c['status']['type']['state']=='in'})
   if len(up)>=8: break
  except: continue
 return jsonify({"live":[x for x in up if x['isLive']],"up":[x for x in up if not x['isLive']][:8],"msg":str(len(up)) if len(up)>0 else "موسم منتهي"})
@app.route('/api/standing/<lg>')
def st(lg):
 try:
  r=requests.get(f"https://site.api.espn.com/apis/site/v2/sports/soccer/{lg}/standings",timeout=5)
  e=r.json()['children'][0]['standings']['entries']
  return jsonify({"standing":[{"pos":i+1,"team":x['team']['displayName'],"points":int({s['name']:s['value'] for s in x['stats']}.get('points',0))} for i,x in enumerate(e[:12])]})
 except: return jsonify({"standing":[]})
if __name__=='__main__': app.run(host='0.0.0.0',port=10000)
